def compute(vars):
    gross_profit = vars["Gross Profit"]
    sales = vars["Sales"]
    multiplier = vars["100"]

    if sales == 0:
        return None

    gross_margin = (gross_profit / sales) * multiplier
    return {
        "value": gross_margin,
        "trace": {
            "Gross Profit": gross_profit,
            "Sales": sales,
            "100": multiplier,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
